import React, { useContext, useState, useEffect } from 'react';
import { DataContext } from '../context/DataContext';
import { Shield, Trash2, Filter, AlertTriangle, CheckCircle, PlusCircle, Wrench, Fuel, CreditCard, Truck, Users, Check, X, Edit2, Save, RotateCcw } from 'lucide-react';

const ACTION_LABELS = {
    SEFER_EKLE: { label: 'Sefer Eklendi', color: 'text-emerald-400', bg: 'bg-emerald-500/10 border-emerald-500/20' },
    SEFER_S─░L: { label: 'Sefer Silindi', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' },
    MAZOT_EKLE: { label: 'Mazot Eklendi', color: 'text-blue-400', bg: 'bg-blue-500/10 border-blue-500/20' },
    MAZOT_S─░L: { label: 'Mazot Silindi', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' },
    BAKIM_EKLE: { label: 'Bak─▒m Eklendi', color: 'text-amber-400', bg: 'bg-amber-500/10 border-amber-500/20' },
    BAKIM_S─░L: { label: 'Bak─▒m Silindi', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' },
    ODEME_EKLE: { label: '├ûdeme Eklendi', color: 'text-purple-400', bg: 'bg-purple-500/10 border-purple-500/20' },
    ODEME_S─░L: { label: '├ûdeme Silindi', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' },
    TAM─░RC─░_EKLE: { label: 'Tamirci Eklendi', color: 'text-cyan-400', bg: 'bg-cyan-500/10 border-cyan-500/20' },
    TAM─░RC─░_S─░L: { label: 'Tamirci Silindi', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' },
    ARAC_GUNCELLE: { label: 'Ara├º G├╝ncellendi', color: 'text-slate-300', bg: 'bg-slate-500/10 border-slate-500/20' },
    NOT_EKLE: { label: 'Not Eklendi', color: 'text-yellow-400', bg: 'bg-yellow-500/10 border-yellow-500/20' },
    KULLANICI_ONAYLA: { label: 'Kullan─▒c─▒ Onayland─▒', color: 'text-emerald-400', bg: 'bg-emerald-500/10 border-emerald-500/20' },
    KULLANICI_RED: { label: 'Kullan─▒c─▒ Reddedildi', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' },
    KULLANICI_GIRIS: { label: 'Oturum A├º─▒ld─▒', color: 'text-sky-400', bg: 'bg-sky-500/10 border-sky-500/20' },
    KULLANICI_EKLE: { label: 'Man├╝el Ekleme', color: 'text-indigo-400', bg: 'bg-indigo-500/10 border-indigo-500/20' },
    KULLANICI_DUZENLE: { label: 'D├╝zenleme', color: 'text-slate-400', bg: 'bg-white/5 border-white/10' },
};

const AdminLog = () => {
    const { adminLog, clearLog, pendingUsers, approvedUsers, approveUser, rejectUser, editUser, refreshUsers, restoreData, addApprovedUser } = useContext(DataContext);
    const [filter, setFilter] = useState('TUMU');
    const [tab, setTab] = useState('log'); // 'log' | 'users'
    const [confirmClear, setConfirmClear] = useState(false);

    // Yeni: Man├╝el Kullan─▒c─▒ Modal
    const [isAddUserModalOpen, setIsAddUserModalOpen] = useState(false);
    const [newUserForm, setNewUserForm] = useState({ username: '', password: '', role: '┼ƒof├╢r' });

    // Yeni: Kullan─▒c─▒ Y├╢netimi State'leri
    const [approvalRoles, setApprovalRoles] = useState({});
    const [editingUserId, setEditingUserId] = useState(null);
    const [editForm, setEditForm] = useState({ username: '', password: '', role: '┼ƒof├╢r' });

    const handleEditStart = (u) => {
        setEditingUserId(u.id);
        setEditForm({ username: u.username, password: u.password, role: u.role || '┼ƒof├╢r' });
    };

    const handleEditSave = async (userId) => {
        // D├╝zenleme s─▒ras─▒nda ┼ƒifre de btoa ile hashlenmeli
        const formToSave = { ...editForm, password: btoa(editForm.password) };
        const success = await editUser(userId, formToSave);
        setEditingUserId(null);
        if (refreshUsers) refreshUsers();
    };

    const handleAddManualUser = async (e) => {
        e.preventDefault();
        const hashedPassword = btoa(newUserForm.password);
        await addApprovedUser({ ...newUserForm, password: hashedPassword });
        setIsAddUserModalOpen(false);
        setNewUserForm({ username: '', password: '', role: '┼ƒof├╢r' });
        if (refreshUsers) refreshUsers();
    };

    const handleApprove = (userId) => {
        const role = approvalRoles[userId] || '┼ƒof├╢r';
        approveUser(userId, role);
        setApprovalRoles(prev => { const n = { ...prev }; delete n[userId]; return n; });
    };

    // Sekme de─ƒi┼ƒti─ƒinde veya bile┼ƒen y├╝klendi─ƒinde kullan─▒c─▒ listesini localStorage'dan tazele
    useEffect(() => {
        if (tab === 'users' && refreshUsers) {
            refreshUsers();
        }
    }, [tab, refreshUsers]);

    const categories = [
        { key: 'TUMU', label: 'T├╝m├╝' },
        { key: 'EKLE', label: 'Eklemeler' },
        { key: 'S─░L', label: 'Silmeler' },
        { key: 'KULLANICI', label: 'Kullan─▒c─▒lar' },
    ];

    const filteredLog = adminLog.filter(entry => {
        if (filter === 'TUMU') return true;
        if (filter === 'EKLE') return entry.action.includes('EKLE');
        if (filter === 'S─░L') return entry.action.includes('S─░L');
        if (filter === 'KULLANICI') return entry.action.includes('KULLANICI');
        return true;
    });

    const handleClear = () => {
        if (confirmClear) { clearLog(); setConfirmClear(false); }
        else { setConfirmClear(true); setTimeout(() => setConfirmClear(false), 4000); }
    };

    return (
        <div className="space-y-5 animate-in fade-in duration-500">
            {/* Header */}
            <div className="flex items-center gap-3">
                <div className="p-2 bg-brand-500/10 rounded-xl border border-brand-500/20">
                    <Shield size={20} className="text-brand-400" />
                </div>
                <div>
                    <h3 className="font-semibold text-white">Admin Paneli</h3>
                    <p className="text-xs text-slate-500">{adminLog.length} log ┬╖ {pendingUsers.length} bekleyen talep</p>
                </div>
            </div>

            {/* Tab Switcher */}
            <div className="flex gap-1 bg-white/5 p-1 rounded-xl">
                <button onClick={() => setTab('log')}
                    className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${tab === 'log' ? 'bg-brand-500/20 text-brand-300 border border-brand-500/30' : 'text-slate-400 hover:text-slate-200'}`}>
                    Aktivite Logu
                </button>
                <button onClick={() => setTab('users')}
                    className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all flex items-center justify-center gap-2 ${tab === 'users' ? 'bg-brand-500/20 text-brand-300 border border-brand-500/30' : 'text-slate-400 hover:text-slate-200'}`}>
                    <Users size={14} /> Kullan─▒c─▒lar
                    {pendingUsers.length > 0 && (
                        <span className="bg-red-500 text-white text-xs w-4 h-4 rounded-full flex items-center justify-center">{pendingUsers.length}</span>
                    )}
                </button>
            </div>

            {/* Aktivite Logu */}
            {tab === 'log' && (
                <>
                    <div className="flex items-center justify-between gap-2 flex-wrap">
                        <div className="flex gap-1.5 flex-wrap">
                            {categories.map(cat => (
                                <button key={cat.key} onClick={() => setFilter(cat.key)}
                                    className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${filter === cat.key ? 'bg-brand-500/20 text-brand-300 border border-brand-500/30' : 'bg-white/5 text-slate-400 hover:bg-white/10'}`}>
                                    {cat.label}
                                </button>
                            ))}
                        </div>
                        {/* 'Temizle' butonu kald─▒r─▒ld─▒, loglar kal─▒c─▒ yap─▒ld─▒ */}
                    </div>

                    <div className="glass-panel overflow-hidden">
                        {filteredLog.length === 0 ? (
                            <div className="p-10 text-center">
                                <CheckCircle size={28} className="mx-auto mb-3 text-slate-600" />
                                <p className="text-slate-500 text-sm">Kay─▒t yok</p>
                            </div>
                        ) : (
                            <div className="divide-y divide-white/5">
                                {filteredLog.map(entry => {
                                    const meta = ACTION_LABELS[entry.action] || { label: entry.action, color: 'text-slate-400', bg: 'bg-white/5 border-white/10' };
                                    const date = new Date(entry.timestamp);
                                    return (
                                        <div key={entry.id} className="flex items-start gap-3 p-3 hover:bg-white/5 transition-colors">
                                            <span className={`flex items-center gap-1.5 px-2 py-0.5 rounded-full text-xs font-medium border whitespace-nowrap mt-0.5 flex-shrink-0 ${meta.bg} ${meta.color}`}>
                                                {meta.label}
                                            </span>
                                            <div className="flex-1 min-w-0">
                                                <p className="text-slate-300 text-sm truncate">{entry.detail}</p>
                                                <p className="text-xs text-slate-600">
                                                    {entry.user}
                                                    {entry.action === 'KULLANICI_GIRIS' && entry.meta && (
                                                        <span className="ml-2 text-[10px] text-slate-500">
                                                            ΓÇó IP: {entry.meta.ip} ΓÇó {entry.meta.device?.split(')')[0]?.split('(')[1] || 'PC'}
                                                        </span>
                                                    )}
                                                </p>
                                            </div>
                                            <div className="text-right flex-shrink-0 flex flex-col items-end gap-1">
                                                <div className="flex flex-col items-end">
                                                    <p className="text-xs text-slate-500">{date.toLocaleDateString('tr-TR')}</p>
                                                    <p className="text-xs text-slate-600">{date.toLocaleTimeString('tr-TR', { hour: '2-digit', minute: '2-digit' })}</p>
                                                </div>
                                                {entry.action.includes('S─░L') && entry.meta && (
                                                    <button onClick={() => restoreData(entry.meta.table, entry.meta.id)}
                                                        className="flex items-center gap-1 text-[10px] bg-brand-500/20 text-brand-400 px-2 py-1 rounded hover:bg-brand-500/30 transition-colors mt-1">
                                                        <RotateCcw size={10} /> Geri Y├╝kle
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                </>
            )}

            {/* Kullan─▒c─▒ Y├╢netimi */}
            {tab === 'users' && (
                <div className="space-y-4">
                    {/* Bekleyen Talepler */}
                    <div>
                        <h4 className="text-sm font-semibold text-slate-300 mb-2 flex items-center gap-2">
                            ΓÅ│ Onay Bekleyen
                            {pendingUsers.length > 0 && (
                                <span className="bg-amber-500/20 text-amber-400 border border-amber-500/30 text-xs px-2 py-0.5 rounded-full">{pendingUsers.length}</span>
                            )}
                        </h4>
                        {pendingUsers.length === 0 ? (
                            <div className="glass-panel p-6 text-center text-slate-500 text-sm">Bekleyen talep yok</div>
                        ) : (
                            <div className="space-y-2">
                                {pendingUsers.map(u => (
                                    <div key={u.id} className="glass-panel p-3 flex items-center gap-3">
                                        <div className="bg-amber-500/20 p-2 rounded-lg flex-shrink-0">
                                            <Users size={16} className="text-amber-400" />
                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <p className="text-white font-medium text-sm">{u.username}</p>
                                            <p className="text-slate-500 text-xs">{new Date(u.requestedAt).toLocaleString('tr-TR')}</p>
                                        </div>
                                        <div className="flex flex-col sm:flex-row gap-2 flex-shrink-0">
                                            <select
                                                value={approvalRoles[u.id] || '┼ƒof├╢r'}
                                                onChange={(e) => setApprovalRoles({ ...approvalRoles, [u.id]: e.target.value })}
                                                className="bg-white/5 border border-white/10 text-white text-xs rounded-lg px-2 py-1.5 focus:outline-none focus:border-brand-500"
                                            >
                                                <option value="┼ƒof├╢r" className="bg-slate-800">┼₧of├╢r</option>
                                                <option value="muhasebe" className="bg-slate-800">Muhasebe</option>
                                                <option value="admin" className="bg-slate-800">Admin</option>
                                            </select>

                                            <button onClick={() => handleApprove(u.id)}
                                                className="flex items-center justify-center gap-1 bg-emerald-500/20 hover:bg-emerald-500/30 text-emerald-400 border border-emerald-500/30 px-3 py-1.5 rounded-lg text-xs font-medium transition">
                                                <Check size={12} /> Onayla
                                            </button>
                                            <button onClick={() => rejectUser(u.id)}
                                                className="flex items-center justify-center gap-1 bg-red-500/10 hover:bg-red-500/20 text-red-400 border border-red-500/20 px-3 py-1.5 rounded-lg text-xs font-medium transition">
                                                <X size={12} /> Reddet
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Onayl─▒ Kullan─▒c─▒lar */}
                    <div>
                        <div className="flex items-center justify-between mb-2">
                            <h4 className="text-sm font-semibold text-slate-300">Γ£à Onayl─▒ Kullan─▒c─▒lar</h4>
                            <button onClick={() => setIsAddUserModalOpen(true)}
                                className="flex items-center gap-1.5 text-xs bg-brand-500/20 hover:bg-brand-500/30 text-brand-300 px-3 py-1.5 rounded-lg border border-brand-500/30 transition">
                                <PlusCircle size={13} /> Manuel Ekle
                            </button>
                        </div>
                        <div className="glass-panel overflow-hidden">
                            <div className="p-3 flex items-center gap-3 border-b border-white/5">
                                <div className="bg-brand-500/20 p-2 rounded-lg"><Shield size={14} className="text-brand-400" /></div>
                                <div className="flex-1">
                                    <p className="text-white font-medium text-sm">kenan</p>
                                    <p className="text-slate-500 text-xs">Admin ┬╖ Sistem y├╢neticisi</p>
                                </div>
                                <span className="text-xs bg-brand-500/10 text-brand-300 border border-brand-500/20 px-2 py-0.5 rounded-full">Admin</span>
                            </div>
                            {approvedUsers.length === 0 && (
                                <p className="p-4 text-center text-slate-600 text-sm">Ba┼ƒka onayl─▒ kullan─▒c─▒ yok</p>
                            )}
                            {approvedUsers.map(u => (
                                <div key={u.id} className="p-3 flex items-start sm:items-center gap-3 border-b border-white/5 last:border-0 flex-col sm:flex-row">
                                    <div className="bg-slate-500/20 p-2 rounded-lg flex-shrink-0"><Users size={14} className="text-slate-400" /></div>

                                    {editingUserId === u.id ? (
                                        <div className="flex-1 flex flex-col sm:flex-row gap-2 w-full">
                                            <input type="text" value={editForm.username} onChange={e => setEditForm({ ...editForm, username: e.target.value })} className="bg-white/5 border border-white/10 text-white text-xs px-2 py-1.5 rounded-lg flex-1" placeholder="Kullan─▒c─▒ Ad─▒" />
                                            <input type="text" value={editForm.password} onChange={e => setEditForm({ ...editForm, password: e.target.value })} className="bg-white/5 border border-white/10 text-white text-xs px-2 py-1.5 rounded-lg flex-1" placeholder="┼₧ifre" />
                                            <select value={editForm.role} onChange={e => setEditForm({ ...editForm, role: e.target.value })} className="bg-white/5 border border-white/10 text-white text-xs px-2 py-1.5 rounded-lg flex-1">
                                                <option value="┼ƒof├╢r" className="bg-slate-800">┼₧of├╢r</option>
                                                <option value="muhasebe" className="bg-slate-800">Muhasebe</option>
                                                <option value="admin" className="bg-slate-800">Admin</option>
                                            </select>
                                            <button onClick={() => handleEditSave(u.id)} className="bg-brand-500/20 text-brand-400 border border-brand-500/30 px-3 py-1.5 rounded-lg text-xs font-medium hover:bg-brand-500/30 w-full sm:w-auto flex justify-center items-center gap-1">
                                                <Save size={12} /> Kaydet
                                            </button>
                                            <button onClick={() => setEditingUserId(null)} className="bg-slate-500/20 text-slate-400 border border-slate-500/30 px-3 py-1.5 rounded-lg text-xs font-medium hover:bg-slate-500/30 w-full sm:w-auto flex justify-center items-center gap-1">
                                                ─░ptal
                                            </button>
                                        </div>
                                    ) : (
                                        <>
                                            <div className="flex-1 w-full flex justify-between sm:justify-start items-center gap-2">
                                                <div>
                                                    <p className="text-white font-medium text-sm flex items-center gap-2">
                                                        {u.username}
                                                        <span className="text-[10px] bg-slate-500/10 text-slate-400 border border-slate-500/20 px-1.5 py-0.5 rounded-md uppercase tracking-wider">{u.role || '┼₧of├╢r'}</span>
                                                    </p>
                                                    <p className="text-slate-500 text-xs mt-0.5">┼₧ifre: [┼₧─░FREL─░] ┬╖ Onay: {new Date(u.approvedAt).toLocaleDateString('tr-TR')}</p>
                                                </div>
                                            </div>
                                            <button onClick={() => handleEditStart(u)} className="text-slate-400 hover:text-white p-1.5 transition-colors bg-white/5 rounded-md mt-2 sm:mt-0 w-full sm:w-auto flex justify-center">
                                                <Edit2 size={14} />
                                            </button>
                                        </>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* Manuel Kullan─▒c─▒ Ekleme Modal─▒ */}
                    {isAddUserModalOpen && (
                        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-slate-950/80 backdrop-blur-md">
                            <div className="glass-panel w-full max-w-sm p-6 relative animate-in zoom-in-95 duration-200">
                                <button onClick={() => setIsAddUserModalOpen(false)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={20} /></button>
                                <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
                                    <PlusCircle className="text-brand-500" /> Yeni Kullan─▒c─▒
                                </h3>
                                <form onSubmit={handleAddManualUser} className="space-y-4">
                                    <div>
                                        <label className="block text-xs font-medium text-slate-400 mb-1">Kullan─▒c─▒ Ad─▒</label>
                                        <input type="text" required value={newUserForm.username}
                                            onChange={e => setNewUserForm({ ...newUserForm, username: e.target.value.toLowerCase().trim() })}
                                            className="w-full glass-input px-4 py-2.5 text-sm" placeholder="├╢rnek_isim" />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-medium text-slate-400 mb-1">┼₧ifre</label>
                                        <input type="text" required value={newUserForm.password}
                                            onChange={e => setNewUserForm({ ...newUserForm, password: e.target.value })}
                                            className="w-full glass-input px-4 py-2.5 text-sm" placeholder="123456" />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-medium text-slate-400 mb-1">Yetki Rol├╝</label>
                                        <select value={newUserForm.role}
                                            onChange={e => setNewUserForm({ ...newUserForm, role: e.target.value })}
                                            className="w-full glass-input px-4 py-2.5 text-sm bg-slate-900">
                                            <option value="┼ƒof├╢r">┼₧of├╢r (Admin Hari├º)</option>
                                            <option value="muhasebe">Muhasebe (K─▒s─▒tl─▒)</option>
                                            <option value="admin">Admin (Tam Yetki)</option>
                                        </select>
                                    </div>
                                    <button type="submit"
                                        className="w-full bg-brand-600 hover:bg-brand-500 text-white py-3 rounded-lg font-semibold transition shadow-lg shadow-brand-500/20 mt-2">
                                        Kullan─▒c─▒y─▒ Olu┼ƒtur
                                    </button>
                                </form>
                            </div>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

export default AdminLog;

import React, { useState, useEffect } from 'react';
import {
    AlertTriangle, FileText, Shield, Car, Calendar, Plus, Trash2,
    Bell, CheckCircle, Clock, X, ChevronDown, Paperclip, User,
    AlertCircle, BookOpen, Banknote
} from 'lucide-react';
import { DataContext } from '../context/DataContext';
import FileUpload from './FileUpload';

// ΓöÇΓöÇ Sabitler ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const PENALTY_TYPES = [
    'H─▒z ─░hlali', 'Belge Eksikli─ƒi', 'K─▒rm─▒z─▒ I┼ƒ─▒k', 'Park Cezas─▒',
    'Akaryak─▒t ─░hlali', '├ûTV ─░hlali', 'Emniyet Kemeri', 'Di─ƒer'
];

const DOC_TYPES = [
    { key: 'bandrol', label: 'Bandrol (MTV)', icon: '≡ƒÅ╖∩╕Å', color: 'text-purple-400', bg: 'bg-purple-500/10 border-purple-500/20', warningDays: 30 },
    { key: 'inspection', label: '├çekici Muayenesi', icon: '≡ƒöì', color: 'text-blue-400', bg: 'bg-blue-500/10 border-blue-500/20', warningDays: 45 },
    { key: 'trailerInspection', label: 'Dorse Muayenesi', icon: '≡ƒöì', color: 'text-cyan-400', bg: 'bg-cyan-500/10 border-cyan-500/20', warningDays: 45 },
    { key: 'insurance', label: 'Trafik Sigortas─▒ (Kasko)', icon: '≡ƒ¢í∩╕Å', color: 'text-emerald-400', bg: 'bg-emerald-500/10 border-emerald-500/20', warningDays: 30 },
    { key: 'k1', label: 'K1 Yetki Belgesi', icon: '≡ƒôï', color: 'text-amber-400', bg: 'bg-amber-500/10 border-amber-500/20', warningDays: 60 },
    { key: 'l1', label: 'L1 Yetki Belgesi', icon: '≡ƒôï', color: 'text-orange-400', bg: 'bg-orange-500/10 border-orange-500/20', warningDays: 60 },
    { key: 'srcBelgesi', label: 'SRC Belgesi (┼₧of├╢r)', icon: '≡ƒæñ', color: 'text-pink-400', bg: 'bg-pink-500/10 border-pink-500/20', warningDays: 60 },
    { key: 'odp', label: '├ûDP / ├ûTV Belgesi', icon: '≡ƒôä', color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20', warningDays: 30 },
];

// ΓöÇΓöÇ Yard─▒mc─▒ Fonksiyonlar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const daysUntil = (dateStr) => {
    if (!dateStr) return null;
    const diff = new Date(dateStr) - new Date();
    return Math.ceil(diff / (1000 * 60 * 60 * 24));
};

const statusBadge = (days) => {
    if (days === null) return { label: 'Tarih Yok', color: 'text-slate-500', bg: 'bg-slate-500/10 border-slate-500/20' };
    if (days < 0) return { label: `${Math.abs(days)} g├╝n ge├ºti!`, color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' };
    if (days <= 30) return { label: `${days} g├╝n kald─▒`, color: 'text-red-400', bg: 'bg-red-500/10 border-red-500/20' };
    if (days <= 60) return { label: `${days} g├╝n kald─▒`, color: 'text-amber-400', bg: 'bg-amber-500/10 border-amber-500/20' };
    return { label: `${days} g├╝n kald─▒`, color: 'text-emerald-400', bg: 'bg-emerald-500/10 border-emerald-500/20' };
};

// ΓöÇΓöÇ Local Storage Yard─▒mc─▒lar─▒ ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const load = (key, def) => { try { return JSON.parse(localStorage.getItem(key)) || def; } catch { return def; } };
const save = (key, val) => localStorage.setItem(key, JSON.stringify(val));

// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ

const Detaylar = () => {
    const {
        docs, updateDocs,
        penalties, addPenalty, deletePenalty, togglePenaltyPaid
    } = React.useContext(DataContext);

    const [activeTab, setActiveTab] = useState('belgeler');

    // Belgeler ve tarihler
    const [editingDoc, setEditingDoc] = useState(null);
    const [docForm, setDocForm] = useState({ date: '', notes: '', files: [] });

    // Cezalar
    const [showPenaltyForm, setShowPenaltyForm] = useState(false);
    const [penaltyForm, setPenaltyForm] = useState({
        date: new Date().toISOString().split('T')[0],
        driver: '',
        type: 'H─▒z ─░hlali',
        amount: '',
        plate: '',
        description: '',
        paid: false,
        files: []
    });

    // Drivers listesi (Maintenance'dan)
    const drivers = load('tir_drivers', [{ name: '┼₧of├╢r' }]);

    // ΓöÇΓöÇ Bildirim Hesaplama ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    const urgentDocs = DOC_TYPES.filter(dt => {
        const d = docs[dt.key];
        if (!d?.date) return false;
        const days = daysUntil(d.date);
        return days !== null && days <= dt.warningDays;
    });

    const unpaidPenalties = penalties.filter(p => !p.paid);

    const totalNotifications = urgentDocs.length + unpaidPenalties.length;

    // ΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

    const saveDoc = () => {
        if (!editingDoc || !docForm.date) return;
        updateDocs({ ...docs, [editingDoc]: docForm });
        setEditingDoc(null);
        setDocForm({ date: '', notes: '', files: [] });
    };

    const openEditDoc = (key) => {
        const existing = docs[key] || { date: '', notes: '', files: [] };
        setDocForm({ date: existing.date || '', notes: existing.notes || '', files: existing.files || [] });
        setEditingDoc(key);
    };

    const handleAddPenalty = (e) => {
        e.preventDefault();
        addPenalty({ ...penaltyForm, id: Date.now(), amount: parseFloat(penaltyForm.amount) || 0 });
        setShowPenaltyForm(false);
        setPenaltyForm({ date: new Date().toISOString().split('T')[0], driver: '', type: 'H─▒z ─░hlali', amount: '', plate: '', description: '', paid: false, files: [] });
    };

    const togglePaid = (id) => {
        const p = penalties.find(pen => pen.id === id);
        if (p) togglePenaltyPaid(id, p.paid);
    };

    const handleDeletePenalty = (id) => {
        deletePenalty(id);
    };

    const tabs = [
        { id: 'belgeler', label: 'Belgeler & Tarihler', icon: <FileText size={15} /> },
        { id: 'cezalar', label: 'Cezalar', icon: <AlertTriangle size={15} /> },
        { id: 'bildirimler', label: 'Bildirimler', icon: <Bell size={15} />, badge: totalNotifications },
    ];

    return (
        <div className="space-y-5 animate-in fade-in duration-500 pb-ios-nav">

            {/* ├ûzet Kartlar─▒ */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                <div className="glass-panel p-3 flex items-center gap-3">
                    <div className="bg-red-500/20 p-2 rounded-lg"><AlertTriangle size={16} className="text-red-400" /></div>
                    <div>
                        <p className="text-xs text-slate-400">Yakla┼ƒan / Ge├ºen</p>
                        <p className="text-lg font-bold text-white">{urgentDocs.length}</p>
                    </div>
                </div>
                <div className="glass-panel p-3 flex items-center gap-3">
                    <div className="bg-amber-500/20 p-2 rounded-lg"><Banknote size={16} className="text-amber-400" /></div>
                    <div>
                        <p className="text-xs text-slate-400">├ûdenmemi┼ƒ Ceza</p>
                        <p className="text-lg font-bold text-white">{unpaidPenalties.length}</p>
                    </div>
                </div>
                <div className="glass-panel p-3 flex items-center gap-3">
                    <div className="bg-amber-500/20 p-2 rounded-lg"><Banknote size={16} className="text-amber-400" /></div>
                    <div>
                        <p className="text-xs text-slate-400">Toplam Ceza Tutar─▒</p>
                        <p className="text-lg font-bold text-white">Γé║{unpaidPenalties.reduce((s, p) => s + p.amount, 0).toLocaleString('tr-TR')}</p>
                    </div>
                </div>
                <div className="glass-panel p-3 flex items-center gap-3">
                    <div className="bg-emerald-500/20 p-2 rounded-lg"><CheckCircle size={16} className="text-emerald-400" /></div>
                    <div>
                        <p className="text-xs text-slate-400">├ûdenen Ceza</p>
                        <p className="text-lg font-bold text-white">{penalties.filter(p => p.paid).length}</p>
                    </div>
                </div>
            </div>

            {/* Tab Bar */}
            <div className="flex gap-1 bg-white/5 p-1 rounded-xl">
                {tabs.map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                        className={`flex-1 flex items-center justify-center gap-1.5 py-2 rounded-lg text-sm font-medium transition-all ${activeTab === tab.id ? 'bg-brand-500/20 text-brand-300 border border-brand-500/30' : 'text-slate-400 hover:text-slate-200'}`}>
                        {tab.icon}
                        <span className="hidden sm:inline">{tab.label}</span>
                        <span className="sm:hidden">{tab.label.split(' ')[0]}</span>
                        {tab.badge > 0 && (
                            <span className="bg-red-500 text-white text-xs w-4 h-4 rounded-full flex items-center justify-center flex-shrink-0">{tab.badge}</span>
                        )}
                    </button>
                ))}
            </div>

            {/* ΓöÇΓöÇΓöÇ BELGELER & TAR─░HLER ΓöÇΓöÇΓöÇ */}
            {activeTab === 'belgeler' && (
                <div className="space-y-3">
                    <p className="text-xs text-slate-500 px-1">Her belge i├ºin son ge├ºerlilik tarihini girin. Belge yakla┼ƒ─▒nca otomatik uyar─▒ al─▒rs─▒n─▒z.</p>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                        {DOC_TYPES.map(dt => {
                            const docData = docs[dt.key];
                            const days = docData?.date ? daysUntil(docData.date) : null;
                            const status = statusBadge(days);
                            return (
                                <div key={dt.key} className={`glass-panel p-4 border ${docData?.date && days !== null && days <= 30 ? 'border-red-500/30' : 'border-white/10'}`}>
                                    <div className="flex items-start justify-between gap-2">
                                        <div className="flex items-center gap-2">
                                            <span className="text-lg">{dt.icon}</span>
                                            <div>
                                                <p className="text-white font-medium text-sm">{dt.label}</p>
                                                {docData?.date ? (
                                                    <p className="text-xs text-slate-400">{new Date(docData.date).toLocaleDateString('tr-TR')}</p>
                                                ) : (
                                                    <p className="text-xs text-slate-600">Tarih girilmedi</p>
                                                )}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2 flex-shrink-0">
                                            {docData?.date && (
                                                <span className={`text-xs px-2 py-0.5 rounded-full border font-medium ${status.bg} ${status.color}`}>
                                                    {status.label}
                                                </span>
                                            )}
                                            <button onClick={() => openEditDoc(dt.key)}
                                                className="text-slate-500 hover:text-brand-400 p-1 rounded transition text-xs border border-white/10 hover:border-brand-500/30 px-2">
                                                D├╝zenle
                                            </button>
                                        </div>
                                    </div>
                                    {docData?.notes && (
                                        <p className="text-xs text-slate-500 mt-2 border-t border-white/5 pt-2">{docData.notes}</p>
                                    )}
                                    {docData?.files?.length > 0 && (
                                        <p className="text-xs text-brand-400 mt-1">≡ƒôÄ {docData.files.length} belge eklendi</p>
                                    )}

                                    {/* Edit Modal (inline) */}
                                    {editingDoc === dt.key && (
                                        <div className="mt-3 border-t border-white/10 pt-3 space-y-3">
                                            <div>
                                                <label className="block text-xs text-slate-400 mb-1">Son Ge├ºerlilik Tarihi</label>
                                                <input type="date" className="w-full glass-input px-3 py-2 text-sm" value={docForm.date}
                                                    onChange={e => setDocForm({ ...docForm, date: e.target.value })} />
                                            </div>
                                            <div>
                                                <label className="block text-xs text-slate-400 mb-1">Not (opsiyonel)</label>
                                                <input type="text" placeholder="├ûrn: Yenileme yap─▒ld─▒, poli├ºe no: ..." className="w-full glass-input px-3 py-2 text-sm" value={docForm.notes}
                                                    onChange={e => setDocForm({ ...docForm, notes: e.target.value })} />
                                            </div>
                                            <div>
                                                <label className="block text-xs text-slate-400 mb-1">≡ƒôÄ Belge / Foto─ƒraf</label>
                                                <FileUpload files={docForm.files} onChange={f => setDocForm({ ...docForm, files: f })} maxSizeMB={5} />
                                            </div>
                                            <div className="flex gap-2">
                                                <button onClick={saveDoc} className="flex-1 bg-brand-600 hover:bg-brand-500 text-white py-2 rounded-lg text-sm font-medium transition">Kaydet</button>
                                                <button onClick={() => setEditingDoc(null)} className="px-4 py-2 text-slate-400 hover:text-white text-sm transition">─░ptal</button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                </div>
            )}

            {/* ΓöÇΓöÇΓöÇ CEZALAR ΓöÇΓöÇΓöÇ */}
            {activeTab === 'cezalar' && (
                <div className="space-y-4">
                    <div className="flex justify-between items-center gap-4 flex-wrap">
                        <div className="space-y-0.5">
                            <p className="text-slate-300 text-sm font-medium">Trafik & Vergi Cezalar─▒</p>
                            <p className="text-slate-500 text-xs">┼₧of├╢re veya araca kesilen cezalar─▒ kay─▒t alt─▒na al─▒n</p>
                        </div>
                        <button onClick={() => setShowPenaltyForm(!showPenaltyForm)}
                            className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded-lg flex items-center gap-2 font-medium text-sm transition">
                            <Plus size={16} /> Ceza Ekle
                        </button>
                    </div>

                    {/* Ceza Ekleme Formu */}
                    {showPenaltyForm && (
                        <div className="glass-panel p-5 border border-red-500/20">
                            <h4 className="font-semibold text-white mb-4 flex items-center gap-2"><AlertTriangle size={16} className="text-red-400" /> Yeni Ceza Kayd─▒</h4>
                            <form onSubmit={handleAddPenalty} className="space-y-4">
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs text-slate-400 mb-1">Tarih</label>
                                        <input type="date" required className="w-full glass-input px-3 py-2 text-sm" value={penaltyForm.date}
                                            onChange={e => setPenaltyForm({ ...penaltyForm, date: e.target.value })} />
                                    </div>
                                    <div>
                                        <label className="block text-xs text-slate-400 mb-1">┼₧of├╢r</label>
                                        <div className="relative">
                                            <select className="w-full glass-input px-3 py-2 text-sm bg-slate-800 appearance-none"
                                                value={penaltyForm.driver} onChange={e => setPenaltyForm({ ...penaltyForm, driver: e.target.value })}>
                                                <option value="">┼₧of├╢r se├º / ara├º</option>
                                                {drivers.map((d, i) => <option key={i} value={d.name}>{d.name}</option>)}
                                                <option value="Ara├º (Plakaya)">Ara├º (Plakaya)</option>
                                            </select>
                                            <ChevronDown size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                        </div>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-xs text-slate-400 mb-1">Ceza T├╝r├╝</label>
                                        <div className="relative">
                                            <select className="w-full glass-input px-3 py-2 text-sm bg-slate-800 appearance-none"
                                                value={penaltyForm.type} onChange={e => setPenaltyForm({ ...penaltyForm, type: e.target.value })}>
                                                {PENALTY_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                                            </select>
                                            <ChevronDown size={12} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-slate-400 mb-1">Tutar (Γé║)</label>
                                        <input type="number" step="0.01" placeholder="0.00" className="w-full glass-input px-3 py-2 text-sm" value={penaltyForm.amount}
                                            onChange={e => setPenaltyForm({ ...penaltyForm, amount: e.target.value })} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-400 mb-1">Ceza Detay─▒</label>
                                    <textarea rows={2} placeholder="├ûrn: Ankara D-100 ├╝zerinde 130km/h h─▒z ihlali, ehliyet puan─▒ kesildi" className="w-full glass-input px-3 py-2 text-sm resize-none"
                                        value={penaltyForm.description} onChange={e => setPenaltyForm({ ...penaltyForm, description: e.target.value })} />
                                </div>
                                <div>
                                    <label className="block text-xs text-slate-400 mb-1">≡ƒôÄ Tutanak / Makbuz Foto─ƒraf─▒</label>
                                    <FileUpload files={penaltyForm.files} onChange={f => setPenaltyForm({ ...penaltyForm, files: f })} />
                                </div>
                                <div className="flex gap-3">
                                    <button type="submit" className="flex-1 bg-red-600 hover:bg-red-500 text-white py-2.5 rounded-lg font-medium text-sm transition">Cezay─▒ Kaydet</button>
                                    <button type="button" onClick={() => setShowPenaltyForm(false)} className="px-4 py-2 text-slate-400 text-sm hover:text-white transition">─░ptal</button>
                                </div>
                            </form>
                        </div>
                    )}

                    {/* Ceza Listesi */}
                    <div className="glass-panel overflow-hidden">
                        {penalties.length === 0 ? (
                            <div className="p-8 text-center">
                                <CheckCircle size={28} className="mx-auto mb-3 text-slate-600" />
                                <p className="text-slate-400 font-medium text-sm">Kay─▒tl─▒ ceza yok</p>
                            </div>
                        ) : (
                            <div className="divide-y divide-white/5">
                                {penalties.map(p => (
                                    <div key={p.id} className={`p-4 hover:bg-white/5 transition-colors ${p.paid ? 'opacity-60' : ''}`}>
                                        <div className="flex items-start gap-3">
                                            <div className={`p-2 rounded-lg flex-shrink-0 ${p.paid ? 'bg-emerald-500/10' : 'bg-red-500/10'}`}>
                                                <AlertTriangle size={16} className={p.paid ? 'text-emerald-400' : 'text-red-400'} />
                                            </div>
                                            <div className="flex-1 min-w-0">
                                                <div className="flex items-center gap-2 flex-wrap">
                                                    <span className="text-white font-semibold text-sm">{p.type}</span>
                                                    {p.driver && <span className="text-xs text-slate-400 flex items-center gap-1"><User size={10} /> {p.driver}</span>}
                                                    <span className="text-xs text-slate-500">{new Date(p.date).toLocaleDateString('tr-TR')}</span>
                                                </div>
                                                {p.description && <p className="text-slate-400 text-xs mt-0.5">{p.description}</p>}
                                                {p.files?.length > 0 && <p className="text-brand-400 text-xs mt-0.5">≡ƒôÄ {p.files.length} belge</p>}
                                            </div>
                                            <div className="flex items-center gap-2 flex-shrink-0">
                                                <span className={`font-bold text-sm ${p.paid ? 'text-emerald-400 line-through' : 'text-red-400'}`}>
                                                    Γé║{p.amount.toLocaleString('tr-TR')}
                                                </span>
                                                <button onClick={() => togglePaid(p.id)}
                                                    title={p.paid ? '├ûdenmedi olarak i┼ƒaretle' : '├ûdendi olarak i┼ƒaretle'}
                                                    className={`p-1.5 rounded-lg transition-all ${p.paid ? 'bg-slate-500/20 text-slate-400 hover:bg-red-500/10 hover:text-red-400' : 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20'}`}>
                                                    <CheckCircle size={14} />
                                                </button>
                                                <button onClick={() => handleDeletePenalty(p.id)}
                                                    className="p-1.5 rounded-lg text-slate-600 hover:text-red-400 hover:bg-red-500/10 transition-all">
                                                    <Trash2 size={14} />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ΓöÇΓöÇΓöÇ B─░LD─░R─░MLER ΓöÇΓöÇΓöÇ */}
            {activeTab === 'bildirimler' && (
                <div className="space-y-4">
                    {totalNotifications === 0 ? (
                        <div className="glass-panel p-10 text-center">
                            <CheckCircle size={36} className="mx-auto mb-3 text-emerald-500/50" />
                            <p className="text-white font-semibold">Her ┼ƒey yolunda!</p>
