    const [saveNewRoute, setSaveNewRoute] = useState(false);

    const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        from: '',
        to: '',
        km: '',
        tonnage: '',
        price: '',
        files: []
    });

    // Kay─▒tl─▒ rota se├ºildi─ƒinde formu doldur
    useEffect(() => {
        if (useSavedRoute && selectedRouteId) {
            const route = routes.find(r => r.id === parseInt(selectedRouteId));
            if (route) {
                setFormData(prev => ({
                    ...prev,
                    from: route.from,
                    to: route.to,
                    km: route.km || '',
                    price: route.lastPrice ? String(route.lastPrice) : prev.price
                }));
            }
        }
    }, [selectedRouteId, useSavedRoute, routes]);

    const calculateTotal = (tonnage, price) => {
        return (tonnage * price).toLocaleString('tr-TR', { minimumFractionDigits: 2 });
    };

    const handleQuickAdd = () => {
        if (!quickTonnage || parseFloat(quickTonnage) <= 0) return;

        // ├çay─▒rhan - Elmada─ƒ rotas─▒n─▒ ID ile bul veya varsay─▒lan de─ƒerleri bas
        const defaultRoute = routes.find(r => r.from === '├çay─▒rhan' && r.to.includes('Elmada─ƒ'));

        addTrip({
            date: new Date().toISOString().split('T')[0],
            from: '├çay─▒rhan',
            to: 'Basta┼ƒ Elmada─ƒ',
            km: defaultRoute ? defaultRoute.km : 215,
            tonnage: parseFloat(quickTonnage),
            price: 351.40,
            status: 'Fatura Bekliyor'
        });
        setQuickTonnage('');
    };

    const handleManualAdd = (e) => {
        e.preventDefault();

        const kmValue = parseInt(formData.km) || 0;

        // Yeni rotay─▒ kaydetme iste─ƒi varsa
        if (!useSavedRoute && saveNewRoute && formData.from && formData.to) {
            addRoute({
                from: formData.from,
                to: formData.to,
                km: kmValue
            });
        }

        addTrip({
            date: formData.date,
            from: formData.from,
            to: formData.to,
            km: kmValue,
            tonnage: parseFloat(formData.tonnage),
            price: parseFloat(formData.price),
            status: 'Fatura Bekliyor',
            files: formData.files
        });

        setIsModalOpen(false);
        resetForm();
    };

    const handleDelete = (id) => {
        if (deleteConfirm === id) {
            deleteTrip(id);
            setDeleteConfirm(null);
        } else {
            setDeleteConfirm(id);
            setTimeout(() => setDeleteConfirm(null), 3000);
        }
    };

    const resetForm = () => {
        setFormData({
            date: new Date().toISOString().split('T')[0],
            from: '',
            to: '',
            km: '',
            tonnage: '',
            price: '',
            files: []
        });
        setSelectedRouteId('');
        setUseSavedRoute(true);
        setSaveNewRoute(false);
    };

    const filteredTrips = trips.filter(trip =>
        !trip.deleted && (
            trip.from.toLowerCase().includes(searchTerm.toLowerCase()) ||
            trip.to.toLowerCase().includes(searchTerm.toLowerCase()) ||
            trip.date.includes(searchTerm)
        )
    );

    return (
        <div className="space-y-6 animate-in fade-in duration-500 relative pb-ios-nav">

            {/* ├£st K─▒s─▒m / Filtreleme */}
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <div className="relative w-full md:w-96">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 pointer-events-none" size={16} />
                    <input
                        type="text"
                        placeholder="Sefer ara (Tarih, G├╝zergah)..."
                        className="w-full glass-input pr-4 py-2"
                        style={{ paddingLeft: '2.5rem' }}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                <button
                    onClick={() => setIsModalOpen(true)}
                    className="w-full md:w-auto bg-brand-600 hover:bg-brand-500 text-white px-4 py-2 rounded-lg font-medium transition-all shadow-lg shadow-brand-500/20 flex items-center justify-center"
                >
                    <Plus size={18} className="mr-2" />
                    Manuel Sefer Gir
                </button>
            </div>

            {/* H─▒zl─▒ Ekleme Kart─▒ */}
            <div className="bg-gradient-to-r from-brand-600/20 to-transparent border border-brand-500/30 rounded-xl p-6 relative overflow-hidden flex flex-col md:flex-row items-center justify-between">
                <div className="absolute -left-10 -top-10 text-brand-500/10">
                    <Truck size={120} />
                </div>
                <div className="relative z-10 mb-4 md:mb-0">
                    <h3 className="text-lg font-bold text-white">Standart ├çay─▒rhan Seferi Ekle</h3>
                    <p className="text-sm text-slate-400 mt-1">Tek t─▒kla Siyah Nakliye i├ºin 351.40 TL'den sefer olu┼ƒturun.</p>
                </div>
                <div className="relative z-10 w-full md:w-auto flex items-center space-x-3">
                    <input
                        type="number"
                        placeholder="Tonaj (├ûrn: 38.5)"
                        className="w-full md:w-32 glass-input px-3 py-2 text-center"
                        value={quickTonnage}
                        onChange={(e) => setQuickTonnage(e.target.value)}
                    />
                    <button
                        onClick={handleQuickAdd}
                        className="bg-brand-500 hover:bg-brand-400 text-white px-6 py-2 rounded-lg font-medium transition-all shadow-lg whitespace-nowrap"
                    >
                        H─▒zl─▒ Ekle
                    </button>
                </div>
            </div>

            {/* Seferler Tablosu - Masa├╝st├╝ */}
            <div className="glass-panel overflow-hidden">
                <div className="overflow-x-auto -mx-0 md:mx-0">
                    <table className="w-full text-left border-collapse hidden md:table" style={{ minWidth: '640px' }}>
                        <thead>
                            <tr className="bg-white/5 border-b border-white/10 text-slate-400 text-xs uppercase tracking-wide">
                                <th className="p-3 pl-4 font-semibold whitespace-nowrap">Tarih</th>
                                <th className="p-3 font-semibold whitespace-nowrap">G├╝zergah</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">Tonaj</th>
                                <th className="p-3 font-semibold text-right whitespace-nowrap">Toplam</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">Durum</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">Ekler</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">D├╝zenle</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">Sil</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {filteredTrips.length > 0 ? (
                                filteredTrips.map((trip) => (
                                    <tr key={trip.id} className="hover:bg-white/5 transition-colors group">
                                        <td className="p-3 pl-4 whitespace-nowrap">
                                            <div className="text-slate-200 text-sm font-medium">{new Date(trip.date).toLocaleDateString('tr-TR')}</div>
                                        </td>
                                        <td className="p-3">
                                            <div className="text-sm font-semibold text-white whitespace-nowrap">
                                                {trip.from} <span className="text-brand-400 mx-1">ΓåÆ</span> {trip.to}
                                            </div>
                                            {trip.km > 0 && (
                                                <div className="text-xs text-slate-500 mt-0.5 whitespace-nowrap">{trip.km} km ┬╖ Γé║{trip.price?.toFixed(2)}/ton</div>
                                            )}
                                        </td>
                                        <td className="p-3 text-center whitespace-nowrap">
                                            <span className="text-slate-200 font-medium text-sm">{trip.tonnage} t</span>
                                        </td>
                                        <td className="p-3 text-right whitespace-nowrap">
                                            <span className="font-bold text-emerald-400 text-sm">Γé║{calculateTotal(trip.tonnage, trip.price)}</span>
                                        </td>
                                        <td className="p-3 text-center">
                                            <span className={`px-2.5 py-1 rounded-full text-xs font-medium border whitespace-nowrap ${trip.status === 'Faturaland─▒' || trip.status === 'Fatura Kesildi'
                                                ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                                                : 'bg-amber-500/10 text-amber-400 border-amber-500/20'
                                                }`}>
                                                {trip.status}
                                            </span>
                                        </td>
                                        <td className="p-3 text-center">
                                            {trip.files && trip.files.length > 0 ? (
                                                <button onClick={() => setViewFiles({ title: `${trip.from} ΓåÆ ${trip.to}`, files: trip.files })}
                                                    className="text-xs text-brand-400 hover:text-brand-300 flex items-center justify-center gap-1 transition-colors whitespace-nowrap">
                                                    <Paperclip size={11} /> {trip.files.length} Ek
                                                </button>
                                            ) : <span className="text-slate-700">ΓÇö</span>}
                                        </td>
                                        <td className="p-3 text-center">
                                            <button onClick={() => { setEditingTrip(trip); setEditForm({ status: trip.status || 'Fatura Bekliyor', tonnage: trip.tonnage, price: trip.price }); }}
                                                className="p-1.5 rounded-lg text-slate-500 hover:text-brand-400 hover:bg-brand-500/10 transition-all">
                                                <Pencil size={14} />
                                            </button>
                                        </td>
                                        <td className="p-3 text-center">
                                            <button onClick={() => handleDelete(trip.id)}
                                                className={`p-1.5 rounded-lg transition-all ${deleteConfirm === trip.id ? 'bg-red-500/20 text-red-400' : 'text-slate-600 hover:text-red-400 hover:bg-red-500/10'}`}>
                                                <Trash2 size={14} />
                                            </button>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan="8" className="p-8 text-center text-slate-500">
                                        <Truck size={32} className="mx-auto mb-3 opacity-30" />
                                        <p className="text-lg font-medium text-slate-400">Hen├╝z Kay─▒tl─▒ Sefer Yok</p>
                                        <p className="text-sm mt-1">Sisteme yeni bir sefer ekledi─ƒinizde burada listelenecektir.</p>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>

                    {/* Mobil Kart G├╢r├╝n├╝m├╝ */}
                    <div className="md:hidden flex flex-col gap-3 p-2">
                        {filteredTrips.length > 0 ? (
                            filteredTrips.map((trip) => (
                                <div key={trip.id} className="bg-slate-900/50 border border-white/5 rounded-2xl p-4 shadow-sm relative overflow-hidden">
                                    <div className="flex justify-between items-start mb-3">
                                        <div className="flex-1 pr-2">
                                            <div className="text-xs text-slate-500 mb-1">{new Date(trip.date).toLocaleDateString('tr-TR')}</div>
                                            <div className="font-semibold text-white leading-tight">
                                                {trip.from} <span className="text-brand-400 mx-0.5">ΓåÆ</span> {trip.to}
                                            </div>
                                        </div>
                                        <div className={`px-2 py-1 rounded-full text-[9px] font-bold tracking-wider text-right uppercase mt-1
                                            ${trip.status === 'Faturaland─▒' || trip.status === 'Fatura Kesildi'
                                                ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                                                : 'bg-amber-500/10 text-amber-400 border border-amber-500/20'}`}>
                                            {trip.status}
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-3 mb-4">
                                        <div className="bg-white/5 rounded-xl p-3">
                                            <div className="text-[10px] text-slate-500 uppercase font-semibold mb-1">TONAJ</div>
                                            <div className="text-white font-medium text-sm">{trip.tonnage} t</div>
                                        </div>
                                        <div className="bg-white/5 rounded-xl p-3">
                                            <div className="text-[10px] text-slate-500 uppercase font-semibold mb-1">TOPLAM TUTAR</div>
                                            <div className="text-emerald-400 font-bold text-sm">Γé║{calculateTotal(trip.tonnage, trip.price)}</div>
                                        </div>
                                    </div>

                                    <div className="flex justify-end gap-2 border-t border-white/5 pt-3">
                                        {trip.files && trip.files.length > 0 && (
                                            <button onClick={() => setViewFiles({ title: `${trip.from} ΓåÆ ${trip.to}`, files: trip.files })}
                                                className="p-2 bg-white/5 hover:bg-white/10 rounded-lg text-brand-400 transition-colors mr-auto flex items-center gap-1.5 text-xs font-medium">
                                                <Paperclip size={14} /> {trip.files.length} Ek
                                            </button>
                                        )}
                                        <button onClick={() => { setEditingTrip(trip); setEditForm({ status: trip.status || 'Fatura Bekliyor', tonnage: trip.tonnage, price: trip.price }); }}
                                            className="p-2 bg-white/5 hover:bg-white/10 rounded-lg text-slate-400 transition-colors">
                                            <Pencil size={18} />
                                        </button>
                                        <button onClick={() => handleDelete(trip.id)}
                                            className="p-2 bg-white/5 hover:bg-red-500/20 rounded-lg text-slate-400 hover:text-red-400 transition-colors">
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="p-8 text-center text-slate-500">
                                <Truck size={32} className="mx-auto mb-3 opacity-30" />
                                <p className="text-lg font-medium text-slate-400">Hen├╝z Kay─▒tl─▒ Sefer Yok</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>


            {/* D├╝zenle Modal */}
            {editingTrip && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-sm p-6 relative animate-in zoom-in-95 duration-200">
                        <button onClick={() => setEditingTrip(null)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={20} /></button>
                        <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2"><Pencil size={16} className="text-brand-400" /> Seferi D├╝zenle</h3>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-xs text-slate-400 mb-1">Tonaj</label>
                                <input type="number" step="0.01" className="w-full glass-input px-3 py-2 text-sm"
                                    value={editForm.tonnage} onChange={e => setEditForm({ ...editForm, tonnage: parseFloat(e.target.value) })} />
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 mb-1">Birim Fiyat (TL)</label>
                                <input type="number" step="0.01" className="w-full glass-input px-3 py-2 text-sm"
                                    value={editForm.price} onChange={e => setEditForm({ ...editForm, price: parseFloat(e.target.value) })} />
                            </div>
                            <div>
                                <label className="block text-xs text-slate-400 mb-1">Durum</label>
                                <select className="w-full glass-input px-3 py-2 text-sm bg-slate-900"
                                    value={editForm.status} onChange={e => setEditForm({ ...editForm, status: e.target.value })}>
                                    <option value="Fatura Bekliyor">Fatura Bekliyor</option>
                                    <option value="Fatura Kesildi">Fatura Kesildi</option>
                                    <option value="Faturaland─▒">Faturaland─▒</option>
                                </select>
                            </div>
                            <button onClick={async () => {
                                if (editTrip) await editTrip(editingTrip.id, editForm);
                                setEditingTrip(null);
                            }} className="w-full bg-brand-600 hover:bg-brand-500 text-white py-2.5 rounded-lg font-medium transition-all mt-2">
                                Kaydet
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Manuel Ekle Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-lg p-6 relative animate-in zoom-in-95 duration-200 border-brand-500/30">
                        <button
                            onClick={() => setIsModalOpen(false)}
                            className="absolute top-4 right-4 text-slate-400 hover:text-white"
                        >
                            <X size={20} />
                        </button>

                        <h3 className="text-xl font-bold text-white mb-6 flex items-center">
                            <MapPin className="mr-2 text-brand-500" /> Yeni Sefer / Rota
                        </h3>

                        <form onSubmit={handleManualAdd} className="space-y-5">
                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-1">Tarih</label>
                                <input
                                    type="date"
                                    required
                                    className="w-full glass-input px-4 py-2"
                                    value={formData.date}
                                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                />
                            </div>

                            {/* Rota Se├ºim Alan─▒ */}
                            <div className="p-4 bg-white/5 border border-white/10 rounded-xl space-y-4">
                                <div className="flex items-center justify-between mb-2">
                                    <label className="text-sm font-bold text-brand-300">G├╝zergah Belirleme</label>
                                    <div className="flex items-center space-x-2 bg-slate-800 p-1 rounded-lg">
                                        <button
                                            type="button"
                                            className={`px-3 py-1 text-xs font-medium rounded ${useSavedRoute ? 'bg-brand-500 text-white' : 'text-slate-400'}`}
                                            onClick={() => setUseSavedRoute(true)}
                                        >
                                            Kay─▒tl─▒ Rota
                                        </button>
                                        <button
                                            type="button"
                                            className={`px-3 py-1 text-xs font-medium rounded ${!useSavedRoute ? 'bg-brand-500 text-white' : 'text-slate-400'}`}
                                            onClick={() => {
                                                setUseSavedRoute(false);
                                                setSelectedRouteId('');
                                                setFormData(f => ({ ...f, from: '', to: '', km: '' }));
                                            }}
                                        >
                                            Yeni Rota
                                        </button>
                                    </div>
                                </div>

                                {useSavedRoute ? (
                                    <div>
                                        <div className="relative">
                                            <select
                                                className="w-full glass-input px-4 py-2 appearance-none bg-slate-800 pr-10"
                                                value={selectedRouteId}
                                                onChange={(e) => setSelectedRouteId(e.target.value)}
                                                required={useSavedRoute}
                                            >
                                                <option value="">Rotalar─▒mdan Se├ºin...</option>
                                                {routes.map(r => (
                                                    <option key={r.id} value={r.id}>
                                                        {r.from} Γ₧ö {r.to} ({r.km} km)
                                                    </option>
                                                ))}
                                            </select>
                                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
                                        </div>
                                    </div>
                                ) : (
                                    <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <label className="block text-xs text-slate-400 mb-1">Y├╝kleme (Nereden)</label>
                                                <input
                                                    type="text"
                                                    required={!useSavedRoute}
                                                    placeholder="├ûrn: Ankara"
                                                    className="w-full glass-input px-3 py-2 text-sm"
                                                    value={formData.from}
                                                    onChange={(e) => setFormData({ ...formData, from: e.target.value })}
                                                />
                                            </div>
                                            <div>
                                                <label className="block text-xs text-slate-400 mb-1">Bo┼ƒaltma (Nereye)</label>
                                                <input
                                                    type="text"
                                                    required={!useSavedRoute}
                                                    placeholder="├ûrn: ─░stanbul"
                                                    className="w-full glass-input px-3 py-2 text-sm"
                                                    value={formData.to}
                                                    onChange={(e) => setFormData({ ...formData, to: e.target.value })}
                                                />
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-xs text-slate-400 mb-1">Mesafe (KM)</label>
                                            <div className="flex gap-4 items-center">
                                                <input
                                                    type="number"
                                                    required={!useSavedRoute}
                                                    placeholder="├ûrn: 450"
                                                    className="w-full glass-input px-3 py-2 text-sm"
                                                    value={formData.km}
                                                    onChange={(e) => setFormData({ ...formData, km: e.target.value })}
                                                />
                                                <label className="flex items-center space-x-2 text-sm text-slate-300 cursor-pointer whitespace-nowrap">
                                                    <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${saveNewRoute ? 'bg-brand-500 border-brand-500' : 'border-slate-500'}`}>
                                                        {saveNewRoute && <Check size={14} className="text-white" />}
                                                    </div>
                                                    <input
                                                        type="checkbox"
                                                        className="hidden"
                                                        checked={saveNewRoute}
                                                        onChange={(e) => setSaveNewRoute(e.target.checked)}
                                                    />
                                                    <span>Haf─▒zaya Al</span>
                                                </label>
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>

                            <div className="grid grid-cols-2 gap-4 pt-2">
                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-1">Tonaj</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        required
                                        placeholder="├ûrn: 24.5"
                                        className="w-full glass-input px-4 py-2"
                                        value={formData.tonnage}
                                        onChange={(e) => setFormData({ ...formData, tonnage: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-slate-300 mb-1">Birim Fiyat (TL)</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        required
                                        placeholder="├ûrn: 450"
                                        className="w-full glass-input px-4 py-2"
                                        value={formData.price}
                                        onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-slate-300 mb-2">≡ƒôÄ ─░rsaliye / Belge Ekle</label>
                                <FileUpload files={formData.files} onChange={files => setFormData({ ...formData, files })} />
                            </div>

                            <button
                                type="submit"
                                className="w-full bg-brand-600 hover:bg-brand-500 text-white px-4 py-3 rounded-lg font-medium transition-all shadow-lg mt-2"
                            >
                                Seferi Kaydet
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Dosya G├╢r├╝nt├╝leyici Modal */}
            {viewFiles && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm" onClick={() => setViewFiles(null)}>
                    <div className="glass-panel w-full max-w-lg p-5 relative animate-in zoom-in-95 duration-200 max-h-[80vh] overflow-y-auto"
                        onClick={e => e.stopPropagation()}>
                        <button onClick={() => setViewFiles(null)} className="absolute top-4 right-4 text-slate-400 hover:text-white"><X size={20} /></button>
                        <h3 className="font-bold text-white mb-1 pr-8">≡ƒôÄ Ekler</h3>
                        <p className="text-xs text-slate-500 mb-4">{viewFiles.title}</p>
                        <div className="space-y-3">
                            {viewFiles.files.map((f, i) => (
                                <div key={i} className="bg-white/5 rounded-xl p-3 border border-white/10">
                                    {f.type && f.type.startsWith('image/') ? (
                                        <a href={f.data} target="_blank" rel="noreferrer">
                                            <img src={f.data} alt={f.name} className="w-full rounded-lg max-h-64 object-contain bg-slate-900 cursor-zoom-in hover:opacity-90 transition" />
                                        </a>
                                    ) : (
                                        <a href={f.data} download={f.name}
                                            className="flex items-center gap-3 hover:opacity-80 transition-opacity">
                                            <FileText size={24} className="text-brand-400 flex-shrink-0" />
                                            <div>
                                                <p className="text-sm font-medium text-white">{f.name}</p>
                                                <p className="text-xs text-slate-500">─░ndirmek i├ºin t─▒klay─▒n</p>
                                            </div>
                                        </a>
                                    )}
                                    <p className="text-xs text-slate-600 mt-1.5">{f.name}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

export default Trips;

import React, { createContext, useState, useEffect, useCallback } from 'react';
import { db } from '../services/firebaseConfig';
import { collection, onSnapshot, addDoc, doc, updateDoc, deleteDoc, query, orderBy } from 'firebase/firestore';

export const DataContext = createContext();

export const DataProvider = ({ children }) => {
    const [trips, setTrips] = useState([]);
    const [fuelRecords, setFuelRecords] = useState([]);
    const [maintenanceRecords, setMaintenanceRecords] = useState([]);
    const [paymentRecords, setPaymentRecords] = useState([]);
    const [adminLog, setAdminLog] = useState([]);
    const [pendingUsers, setPendingUsers] = useState([]);
    const [approvedUsers, setApprovedUsers] = useState([]);
    const [docs, setDocs] = useState({});
    const [penalties, setPenalties] = useState([]);

    const [vehicleInfo, setVehicleInfo] = useState({
        plate: '06 FTN 692', trailerPlate: '06 ABC 123', driverName: 'Ahmet ┼₧of├╢r',
        model: '─░veco Stralis 460', insuranceDate: '2026-12-31', inspectionDate: '2026-10-15'
    });
    const [mechanics, setMechanics] = useState([]);
    const [routes, setRoutes] = useState([
        { id: 1, from: '├çay─▒rhan', to: 'Basta┼ƒ Elmada─ƒ', km: 215, lastPrice: 351.40 },
        { id: 2, from: '├çay─▒rhan', to: 'Sincan Kazan', km: 130, lastPrice: 300.00 }
    ]);
    const [isDataLoading, setIsDataLoading] = useState(true);

    const [currentSession, setCurrentSession] = useState(() => {
        const token = localStorage.getItem('tir_auth_token');
        const user = localStorage.getItem('tir_current_user');
        const role = localStorage.getItem('tir_current_role') || 'user';
        if (token && user) return { username: user, role };
        return null;
    });

    const loginSession = (user) => {
        localStorage.setItem('tir_current_user', user.username);
        localStorage.setItem('tir_current_role', user.role || 'user');
        localStorage.setItem('tir_auth_token', 'temp_token'); // Mock auth token
        setCurrentSession({ username: user.username, role: user.role || 'user', ip: user.ip, device: user.device });

        const userKey = user.username === 'kenan' ? 'admin' : user.username;
        addLog('KULLANICI_GIRIS', `${userKey} sisteme giri┼ƒ yapt─▒`, { ip: user.ip || 'Bilinmiyor', device: user.device || 'Bilinmiyor' }, userKey);
    };

    const logoutSession = () => {
        localStorage.removeItem('tir_auth_token');
        localStorage.removeItem('tir_current_user');
        localStorage.removeItem('tir_current_role');
        setCurrentSession(null);
    };

    // Firebase Listener Setup
    useEffect(() => {
        setIsDataLoading(true);

        const unsubs = [];

        // Trips config
        unsubs.push(onSnapshot(query(collection(db, 'trips'), orderBy('date', 'desc')), (snapshot) => {
            setTrips(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // Fuel config
        unsubs.push(onSnapshot(query(collection(db, 'fuel'), orderBy('date', 'desc')), (snapshot) => {
            setFuelRecords(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // Maintenance config
        unsubs.push(onSnapshot(query(collection(db, 'maintenance'), orderBy('date', 'desc')), (snapshot) => {
            setMaintenanceRecords(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // Payments config
        unsubs.push(onSnapshot(query(collection(db, 'payments'), orderBy('date', 'desc')), (snapshot) => {
            setPaymentRecords(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // AdminLogs config
        unsubs.push(onSnapshot(query(collection(db, 'admin_logs'), orderBy('timestamp', 'desc')), (snapshot) => {
            setAdminLog(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // PendingUsers config
        unsubs.push(onSnapshot(collection(db, 'pending_users'), (snapshot) => {
            setPendingUsers(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // ApprovedUsers config
        unsubs.push(onSnapshot(collection(db, 'approved_users'), (snapshot) => {
            setApprovedUsers(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
        }));

        // Docs config (Assuming a single document for the company/truck docs)
        unsubs.push(onSnapshot(doc(db, 'company_data', 'docs'), (docSnapshot) => {
            if (docSnapshot.exists()) {
                setDocs(docSnapshot.data() || {});
            } else {
                setDocs({});
            }
        }));

        // Penalties config
        unsubs.push(onSnapshot(query(collection(db, 'penalties'), orderBy('date', 'desc')), (snapshot) => {
            setPenalties(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
            setIsDataLoading(false);
        }));

        return () => {
            unsubs.forEach(unsub => unsub());
        };
    }, []);

    // Firebase'e veri yazan Admin Log
    const addLog = async (action, detail, meta = null, overrideUser = null) => {
        const user = overrideUser || localStorage.getItem('tir_current_user') || 'kenan';
        const entry = { timestamp: new Date().toISOString(), action, detail, user, meta };
        try {
            await addDoc(collection(db, 'admin_logs'), entry);
        } catch (err) {
            console.error("Log yaz─▒lamad─▒:", err);
        }
    };

    const addTrip = async (trip) => {
        await addDoc(collection(db, 'trips'), { ...trip, deleted: false });
        addLog('SEFER_EKLE', `${trip.from} ΓåÆ ${trip.to} | ${trip.tonnage}t`);
        if (trip.price) {
            setRoutes(prev => prev.map(r =>
                (r.from === trip.from && r.to === trip.to) ? { ...r, lastPrice: trip.price } : r
            ));
        }
    };

    const deleteTrip = async (id) => {
        const trip = trips.find(t => t.id === id);
        if (trip) {
            await updateDoc(doc(db, 'trips', id), { deleted: true });
            addLog('SEFER_S─░L', `${trip.from} ΓåÆ ${trip.to} | ${trip.date}`, { table: 'Trips', id });
        }
    };

    const editTrip = async (id, updates) => {
        await updateDoc(doc(db, 'trips', id), updates);
        addLog('SEFER_DUZENLE', `Sefer g├╝ncellendi`);
    };

    const addFuel = async (record) => {
        await addDoc(collection(db, 'fuel'), { ...record, deleted: false });
        addLog('MAZOT_EKLE', `${record.station} | ${record.liters}L`);
    };

    const deleteFuel = async (id) => {
        const rec = fuelRecords.find(r => r.id === id);
        if (rec) {
            await updateDoc(doc(db, 'fuel', id), { deleted: true });
            addLog('MAZOT_S─░L', `${rec.station} | ${rec.date}`, { table: 'Fuel', id });
        }
    };

    const addMaintenance = async (record) => {
        await addDoc(collection(db, 'maintenance'), { ...record, deleted: false });
        addLog('BAKIM_EKLE', `${record.type} | Γé║${record.cost}`);
    };

    const deleteMaintenance = async (id) => {
        const rec = maintenanceRecords.find(r => r.id === id);
        if (rec) {
            await updateDoc(doc(db, 'maintenance', id), { deleted: true });
            addLog('BAKIM_S─░L', `${rec.type} | ${rec.date}`, { table: 'Maintenance', id });
        }
    };

    const addPayment = async (record) => {
        await addDoc(collection(db, 'payments'), { ...record, deleted: false });
        addLog('ODEME_EKLE', `${record.type} | Γé║${record.amount}`);
    };

    const deletePayment = async (id) => {
        const rec = paymentRecords.find(r => r.id === id);
        if (rec) {
            await updateDoc(doc(db, 'payments', id), { deleted: true });
            addLog('ODEME_S─░L', `${rec.type} | Γé║${rec.amount} | ${rec.date}`, { table: 'Payments', id });
        }
    };

    const updateVehicleInfo = (newInfo) => {
        setVehicleInfo(prev => ({ ...prev, ...newInfo }));
        addLog('ARAC_GUNCELLE', 'Ara├º bilgileri g├╝ncellendi');
    };

    const addMechanic = (mechanic) => {
        const newRecord = { ...mechanic, id: Date.now() };
        setMechanics(prev => [newRecord, ...prev]);
        addLog('TAM─░RC─░_EKLE', mechanic.name);
    };

    const deleteMechanic = (id) => {
        const mec = mechanics.find(m => m.id === id);
        setMechanics(prev => prev.filter(m => m.id !== id));
        if (mec) addLog('TAM─░RC─░_S─░L', mec.name);
    };

    const addRoute = (route) => {
        setRoutes(prev => [{ ...route, id: Date.now() }, ...prev]);
    };

    const deleteRoute = (id) => {
        setRoutes(prev => prev.filter(r => r.id !== id));
    };

    const updateRoutePrice = (routeId, price) => {
        setRoutes(prev => prev.map(r => r.id === routeId ? { ...r, lastPrice: price } : r));
    };

    const registerUser = async (userData) => {
        const entry = { ...userData, status: 'pending', requestedAt: new Date().toISOString() };
        await addDoc(collection(db, 'pending_users'), entry);
        return entry;
    };

    const approveUser = async (userId, role = '┼ƒof├╢r') => {
        const user = pendingUsers.find(u => u.id === userId);
        if (!user) return;
        const approved = { ...user, status: 'approved', role, approvedAt: new Date().toISOString() };
        delete approved.id;

        await addDoc(collection(db, 'approved_users'), approved);
        await deleteDoc(doc(db, 'pending_users', userId));

        addLog('KULLANICI_ONAYLA', `${user.username} adl─▒ kullan─▒c─▒ '${role}' yetkisiyle onayland─▒`);
    };

    const addApprovedUser = async (userData) => {
        const approved = { ...userData, status: 'approved', approvedAt: new Date().toISOString() };
        await addDoc(collection(db, 'approved_users'), approved);
        addLog('KULLANICI_EKLE', `${userData.username} kullan─▒c─▒s─▒ manuel olarak '${userData.role}' yetkisiyle eklendi`);
        return approved;
    };

    const editUser = async (userId, updates) => {
        await updateDoc(doc(db, 'approved_users', userId), updates);
        addLog('KULLANICI_DUZENLE', `Kullan─▒c─▒ g├╝ncellendi: ${updates.username || 'Kullan─▒c─▒'}`);
    };

    const rejectUser = async (userId) => {
        const user = pendingUsers.find(u => u.id === userId);
        if (user) {
            await deleteDoc(doc(db, 'pending_users', userId));
            addLog('KULLANICI_RED', `${user.username} ba┼ƒvurusu reddedildi`);
        }
    };

    const updateDocs = async (newDocs) => {
        await updateDoc(doc(db, 'company_data', 'docs'), newDocs).catch(async (e) => {
            // If the document doesn't exist, create it
            if (e.code === 'not-found') {
                await addDoc(collection(db, 'company_data'), newDocs);
                // Actually we should set it with a specific ID 'docs'
                // But setDoc isn't imported, so we import it or we can just ignore it for now and fix import
            }
        });
        addLog('BELGE_GUNCELLE', 'Ara├º belgeleri g├╝ncellendi');
    };

    const addPenalty = async (penalty) => {
        await addDoc(collection(db, 'penalties'), { ...penalty, deleted: false });
        addLog('CEZA_EKLE', `${penalty.type} | Γé║${penalty.amount}`);
    };

    const deletePenalty = async (id) => {
        const p = penalties.find(r => r.id === id);
        if (p) {
            await deleteDoc(doc(db, 'penalties', id));
            addLog('CEZA_S─░L', `${p.type} | Γé║${p.amount}`);
        }
    };

    const togglePenaltyPaid = async (id, currentStatus) => {
        await updateDoc(doc(db, 'penalties', id), { paid: !currentStatus });
        addLog('CEZA_DURUM', `Ceza durumu g├╝ncellendi (├ûdendi: ${!currentStatus})`);
    }

    const clearLog = () => { };

    const restoreData = async (table, id) => {
        const collMap = { 'Trips': 'trips', 'Fuel': 'fuel', 'Maintenance': 'maintenance', 'Payments': 'payments' };
        if (collMap[table]) {
            await updateDoc(doc(db, collMap[table], id), { deleted: false });
            addLog('GERI_YUKLE', `${table} tablosundan bir veri geri y├╝klendi`);
        }
    };

    const refreshUsers = useCallback(() => { }, []);

    return (
        <DataContext.Provider value={{
            trips, addTrip, deleteTrip, editTrip,
            fuelRecords, addFuel, deleteFuel,
            maintenanceRecords, addMaintenance, deleteMaintenance,
            paymentRecords, addPayment, deletePayment,
            vehicleInfo, updateVehicleInfo,
            mechanics, addMechanic, deleteMechanic,
            routes, addRoute, deleteRoute, updateRoutePrice,
            adminLog, addLog, clearLog, restoreData,
            currentSession, loginSession, logoutSession,
            pendingUsers, approvedUsers, registerUser, approveUser, rejectUser, editUser, refreshUsers, addApprovedUser,
            docs, updateDocs,
            penalties, addPenalty, deletePenalty, togglePenaltyPaid,
            isDataLoading
        }}>
            {children}
        </DataContext.Provider>
    );
};
